/**
 * Physically deletes an issue with its label links, comments and attachments.
 * The project's number watermark is raised first so the number is never
 * reused. Returns what the caller needs to clean up derived state.
 */
export async function purgeIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<{
  commentIds: readonly string[];
  attachmentSizes: readonly number[];
} | null> {
  const db = getDb();
  return db.transaction((tx) => {
    const row = tx
      .select()
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .get();
    if (!row) return null;

    const max = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, row.projectId),
        ),
      )
      .get();
    const highest = max?.value ?? row.number;
    const existing = tx
      .select()
      .from(issueNumberWatermarks)
      .where(eq(issueNumberWatermarks.projectId, row.projectId))
      .get();
    if (!existing) {
      tx.insert(issueNumberWatermarks)
        .values({ orgId, projectId: row.projectId, lastNumber: highest })
        .run();
    } else if (existing.lastNumber < highest) {
      tx.update(issueNumberWatermarks)
        .set({ lastNumber: highest })
        .where(eq(issueNumberWatermarks.projectId, row.projectId))
        .run();
    }

    const commentRows = tx
      .select({ id: comments.id })
      .from(comments)
      .where(
        and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId)),
      )
      .all();
    const attachmentRows = tx
      .select({ sizeBytes: attachments.sizeBytes })
      .from(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          eq(attachments.issueId, issueId),
        ),
      )
      .all();

    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.issueId, issueId),
        ),
      )
      .run();
    tx.delete(comments)
      .where(
        and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId)),
      )
      .run();
    tx.delete(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          eq(attachments.issueId, issueId),
        ),
      )
      .run();
    tx.delete(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .run();

    return {
      commentIds: commentRows.map((c) => c.id),
      attachmentSizes: attachmentRows.map((a) => a.sizeBytes),
    };
  });
}

